// Roll up Events into a per (date, tool, metric, source_config) cost/units meter for the Costs
// tab. FULL RECOMPUTE every run, over the WHOLE Events tab: two runs against the same Events data
// produce byte-identical bucket totals, so the appendOrUpdate write below (matched on
// date+tool+metric+source_config) overwrites each bucket's row with the same numbers instead of
// adding to them. That is the entire idempotency story here — there is no separate "already
// rolled up" marker that could drift out of sync with Events itself.
//
// metric = Events.action (verify / reveal / opener / generate_page / send / ...). Costs.metric is
// documented (SHEET_SCHEMA.md) as "whatever's meterable for that tool" with example names like
// lead_credits / verify_credits that live in COSTS.md — which does not exist yet in this repo.
// Rather than invent a translation table with no source of truth, this reuses the vocabulary
// Events already has. Revisit if COSTS.md is ever written and defines a different one.
//
// "Measure, don't estimate" applies to BOTH numbers this node writes, not just cost:
//   - units (-> Costs.count): summed only from rows that actually carry a numeric `units` value.
//     A row with a blank/non-numeric units is NOT assumed to be 1 — it is counted separately and
//     called out in `notes`, so a partial sum is never mistaken for a complete one.
//   - est_cost_usd: summed only from rows with a real numeric est_cost_usd. A bucket where every
//     contributing row left it blank stays blank ('' — "unknown"), never 0 ('0' would read as
//     "this tool is free", which is a claim nobody has verified).
const rows = $input.all().map(i => i.json || {});
// alwaysOutputData hands back one placeholder item for a completely empty tab; drop it so an
// empty Events tab produces zero buckets rather than one bogus bucket keyed on 'unknown'.
const real = rows.filter(r => Object.keys(r).some(k => String(r[k] ?? '').trim() !== ''));

function dayOf(ts) {
  const m = String(ts || '').trim().match(/^(\d{4}-\d{2}-\d{2})/);
  return m ? m[1] : 'unknown';
}
function numOrNaN(v) {
  if (v === '' || v === null || typeof v === 'undefined') return NaN;
  const n = Number(v);
  return Number.isFinite(n) ? n : NaN;
}

const buckets = new Map();
for (const r of real) {
  const date = dayOf(r.timestamp);
  const tool = String(r.tool || 'unknown').trim() || 'unknown';
  const metric = String(r.action || 'unknown').trim() || 'unknown';
  const source_config = String(r.source_config || '').trim(); // legitimately blank sometimes
  const key = [date, tool, metric, source_config].join('|');

  if (!buckets.has(key)) {
    buckets.set(key, { date, tool, metric, source_config,
      unit_sum: 0, unit_rows: 0, cost_sum: 0, cost_rows: 0, total_rows: 0 });
  }
  const b = buckets.get(key);
  b.total_rows += 1;

  const units = numOrNaN(r.units);
  if (!Number.isNaN(units)) { b.unit_sum += units; b.unit_rows += 1; }

  const cost = numOrNaN(r.est_cost_usd);
  if (!Number.isNaN(cost)) { b.cost_sum += cost; b.cost_rows += 1; }
}

const out = [];
const rowsSeen = real.length;
let rowsWithNoCost = 0;
let rowsWithNoUnits = 0;

for (const b of buckets.values()) {
  const blankCost = b.total_rows - b.cost_rows;
  const blankUnits = b.total_rows - b.unit_rows;
  rowsWithNoCost += blankCost;
  rowsWithNoUnits += blankUnits;

  const notes = [];
  notes.push(`${b.total_rows} event row(s)`);
  notes.push(blankUnits === 0
    ? `units fully recorded`
    : `${blankUnits} row(s) with no units value — count is a partial sum of the other ${b.unit_rows}`);
  notes.push(blankCost === 0
    ? (b.cost_rows > 0 ? `cost fully recorded` : `no rows carried a cost`)
    : (b.cost_rows === 0
        ? `no cost recorded for any row here — est_cost_usd left blank (measure, don't estimate)`
        : `${blankCost} row(s) with no recorded cost — est_cost_usd is a partial sum of the other ${b.cost_rows}`));

  out.push({ json: {
    _kind: 'cost_row',
    date: b.date,
    tool: b.tool,
    metric: b.metric,
    count: b.unit_rows > 0 ? Number(b.unit_sum.toFixed(4)) : '',
    est_cost_usd: b.cost_rows > 0 ? Number(b.cost_sum.toFixed(4)) : '',
    source_config: b.source_config,
    notes: notes.join('; '),
  }});
}

// A run-level summary item, filtered to its own branch below — not written to Costs (it has no
// row of its own there) but visible in the execution record so "how many rows had no cost" is
// answerable without re-deriving it from the bucket rows by hand.
out.push({ json: {
  _kind: 'summary',
  buckets_written: out.length,
  rows_seen: rowsSeen,
  rows_with_no_cost_recorded: rowsWithNoCost,
  rows_with_no_units_recorded: rowsWithNoUnits,
  run_at: new Date().toISOString(),
}});

return out;
